    CREATE TABLE catalog.id_document_type (
      entry_id uuid NOT NULL,
      family text NOT NULL,
      code text NOT NULL,
      owner_partner_id uuid NULL,
      document_family text NOT NULL,
      capture_method_key text NOT NULL,
